CREATE TABLE `oee_entries` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `operator_completion_id` bigint DEFAULT NULL,
  `job_card_item_id` int DEFAULT NULL,
  `process_day_id` int DEFAULT NULL,
  `machine_id` int NOT NULL,
  `operator_user_id` int DEFAULT NULL,
  `operator_master_id` int DEFAULT NULL,
  `operator_employee_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entry_date` date NOT NULL,
  `shift_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `job_card_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_qty` int DEFAULT NULL COMMENT 'Toolroom/Development quantity (nullable, only used for activity entries)',
  `process_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_no` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_category` enum('CNC','VMC') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `formula_profile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `activity_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `cycle_minutes` int unsigned NOT NULL DEFAULT '0',
  `cycle_seconds` tinyint unsigned NOT NULL DEFAULT '0',
  `load_unload_minutes` int unsigned NOT NULL DEFAULT '0',
  `load_unload_seconds` tinyint unsigned NOT NULL DEFAULT '0',
  `ok_qty` int unsigned NOT NULL DEFAULT '0',
  `rejected_qty` int unsigned NOT NULL DEFAULT '0',
  `hold_qty` int unsigned NOT NULL DEFAULT '0',
  `planned_minutes` decimal(12,2) NOT NULL DEFAULT '0.00',
  `run_minutes` decimal(14,4) DEFAULT NULL,
  `total_loss_minutes` decimal(12,2) DEFAULT NULL,
  `ideal_cycle_minutes` decimal(10,4) DEFAULT NULL,
  `target_qty` decimal(14,4) DEFAULT NULL,
  `total_qty` int DEFAULT NULL,
  `plan_vs_actual` decimal(14,6) DEFAULT NULL,
  `available_time_minutes` decimal(12,2) NOT NULL DEFAULT '0.00',
  `ar_loss_minutes` decimal(12,2) DEFAULT NULL,
  `utilization_minutes` decimal(12,2) DEFAULT NULL,
  `pr_loss_minutes` decimal(12,2) DEFAULT NULL,
  `after_pr_minutes` decimal(12,2) DEFAULT NULL,
  `detailed_ar_ratio` decimal(14,8) DEFAULT NULL,
  `detailed_pr_ratio` decimal(14,8) DEFAULT NULL,
  `detailed_qr_ratio` decimal(14,8) DEFAULT NULL,
  `detailed_oee_ratio` decimal(14,8) DEFAULT NULL,
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `record_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `entry_state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `undone_at` datetime DEFAULT NULL,
  `undone_by_user_id` int DEFAULT NULL,
  `undo_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oee_operator_completion` (`operator_completion_id`),
  KEY `idx_oee_entry_date_machine` (`entry_date`,`machine_id`),
  KEY `idx_oee_job_card_process` (`job_card_no`,`process_name`),
  KEY `idx_oee_operator_date` (`operator_user_id`,`entry_date`),
  KEY `idx_oee_status` (`record_status`),
  KEY `fk_oee_entry_job_card_item` (`job_card_item_id`),
  KEY `fk_oee_entry_process_day` (`process_day_id`),
  KEY `fk_oee_entry_machine` (`machine_id`),
  KEY `fk_oee_entry_undone_by` (`undone_by_user_id`),
  KEY `idx_entry_state` (`entry_state`),
  CONSTRAINT `fk_oee_entry_completion` FOREIGN KEY (`operator_completion_id`) REFERENCES `operator_completion_log` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_oee_entry_job_card_item` FOREIGN KEY (`job_card_item_id`) REFERENCES `job_card_items` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_oee_entry_machine` FOREIGN KEY (`machine_id`) REFERENCES `oee_machines` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_oee_entry_operator` FOREIGN KEY (`operator_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_oee_entry_process_day` FOREIGN KEY (`process_day_id`) REFERENCES `job_card_process_days` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_oee_entry_undone_by` FOREIGN KEY (`undone_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_oee_cycle_seconds` CHECK ((`cycle_seconds` between 0 and 59)),
  CONSTRAINT `chk_oee_load_seconds` CHECK ((`load_unload_seconds` between 0 and 59))
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
