--
-- Table structure for table `oee_entry_losses`
--

DROP TABLE IF EXISTS `oee_entry_losses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oee_entry_losses` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `oee_entry_id` bigint NOT NULL,
  `loss_type_id` int NOT NULL,
  `loss_code_snapshot` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `loss_name_snapshot` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `loss_category_snapshot` enum('AR','PR') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loss_minutes` decimal(12,2) NOT NULL DEFAULT '0.00',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oee_entry_loss_type` (`oee_entry_id`,`loss_type_id`),
  KEY `idx_oee_entry_loss_category` (`oee_entry_id`,`loss_category_snapshot`),
  KEY `fk_oee_loss_type` (`loss_type_id`),
  CONSTRAINT `fk_oee_loss_entry` FOREIGN KEY (`oee_entry_id`) REFERENCES `oee_entries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_oee_loss_type` FOREIGN KEY (`loss_type_id`) REFERENCES `oee_loss_types` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_oee_loss_minutes` CHECK ((`loss_minutes` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=2977 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

