  `loss_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `loss_name` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `loss_category` enum('AR','PR') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
