--
-- Table structure for table `oee_tool_entries`
--

DROP TABLE IF EXISTS `oee_tool_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oee_tool_entries` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint DEFAULT NULL,
  `machine_id` int NOT NULL,
  `run_id` bigint DEFAULT NULL,
  `activity_run_id` bigint DEFAULT NULL,
  `machine_loss_entry_id` bigint DEFAULT NULL,
  `tool_entry_batch_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_user_id` int DEFAULT NULL,
  `operator_master_id` int DEFAULT NULL,
  `operator_employee_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entry_date` date DEFAULT NULL,
  `shift_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tool_position` int NOT NULL,
  `tool_position_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reference to oee_reference_master.reference_code where reference_type=TOOL_POSITION',
  `tool_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tool_life` decimal(14,3) DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tool_action_master_id` int DEFAULT NULL,
  `tool_action_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tool_action_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `corner_master_id` int DEFAULT NULL,
  `corner_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `corner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `change_reason_master_id` int DEFAULT NULL,
  `reason_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `change_reason_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `change_reason_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usage_per_part` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oee_tool_run_position` (`run_id`,`tool_position`),
  UNIQUE KEY `uq_oee_tool_activity_position` (`activity_run_id`,`tool_position`),
  UNIQUE KEY `uq_oee_tool_batch_position` (`tool_entry_batch_id`,`tool_position`),
  KEY `idx_oee_tool_session` (`session_id`,`machine_id`),
  KEY `idx_oee_tool_uid` (`tool_uid`),
  KEY `idx_oee_tool_action` (`tool_action_master_id`),
  KEY `idx_oee_tool_corner` (`corner_master_id`),
  KEY `idx_oee_tool_reason` (`change_reason_master_id`),
  KEY `ix_ote_machine_loss_entry` (`machine_loss_entry_id`),
  KEY `idx_oee_tool_independent_lookup` (`machine_id`,`entry_date`,`shift_name`,`tool_entry_batch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

