--
-- Table structure for table `oee_tool_movements`
--

DROP TABLE IF EXISTS `oee_tool_movements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oee_tool_movements` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tool_uid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `movement_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `machine_id` int NOT NULL,
  `machine_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `machine_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_user_id` int DEFAULT NULL,
  `operator_master_id` int DEFAULT NULL,
  `operator_employee_no` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `movement_date` date NOT NULL,
  `movement_time` time NOT NULL,
  `shift_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `condition_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `breakage_reason_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `breakage_reason_text` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `created_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_uid_created` (`tool_uid`,`created_at`),
  KEY `idx_uid_type` (`tool_uid`,`movement_type`),
  KEY `idx_machine_date` (`machine_id`,`movement_date`,`shift_name`),
  KEY `idx_type_created` (`movement_type`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tool Issue/Return movement ledger. Flavor 3: ISSUE auto-created at UID generation, RETURN explicit.';
/*!40101 SET character_set_client = @saved_cs_client */;

